#!/bin/bash
# setup-webapp.sh — GOLDENSKY bot Mini App (gs-webapp) installer, AWS JP box.
# Installs /opt/gs-webapp/{index.html,webapp.py,mascot.webp}, the gs-webapp
# systemd unit (127.0.0.1:8077), Caddy /app/* + /api/* handles on the
# marz.gloriafreeproton.io site block, and a "📱 App ဖွင့်ရန်" web_app
# button (+ menu button) in /opt/gs-bot/bot.py. All payloads are embedded
# below as base64. Run as root:  sudo bash setup-webapp.sh
# This script never reads or prints bot.env secret values.
set -u
DEST=/opt/gs-webapp
APP_HOST=marz.gloriafreeproton.io
APP_URL="https://marz.gloriafreeproton.io/app/"
CADDYFILE=/etc/caddy/Caddyfile
CADDY_BAK=""
BOT_BAK=""
step() { echo ""; echo "=== $* ==="; }
fail() { echo "ERROR: $*" >&2; exit 1; }

step "Preflight"
[ "$(id -u)" = "0" ] || fail "root (sudo) နဲ့ run ပါ"
[ -f /opt/gs-bot/bot.env ] || fail "/opt/gs-bot/bot.env မရှိပါ"
command -v python3 >/dev/null || fail "python3 မရှိပါ"
command -v systemctl >/dev/null || fail "systemctl မရှိပါ"
command -v base64 >/dev/null || fail "base64 မရှိပါ"
command -v curl >/dev/null || fail "curl မရှိပါ"
[ -f "$CADDYFILE" ] || fail "$CADDYFILE မရှိပါ"
echo "preflight OK"

step "Install payloads to $DEST"
mkdir -p "$DEST" || fail "mkdir $DEST မရပါ"

# ===== payload: index.html (30208 bytes) =====
base64 -d > "$DEST/index.html" <<'GSWA_EOF_INDEX_HTML' || fail "index.html payload decode failed"
