GSWA_EOF_MASCOT_WEBP

chmod 0644 "$DEST/index.html" "$DEST/webapp.py" "$DEST/mascot.webp" || fail "chmod မရပါ"
ls -l "$DEST"
python3 -m py_compile "$DEST/webapp.py" || fail "webapp.py compile မရပါ"
echo "payloads OK"

step "systemd unit: gs-webapp"
cat > /etc/systemd/system/gs-webapp.service <<'EOF_UNIT'
[Unit]
Description=GOLDENSKY bot Mini App (gs-webapp)
After=network.target

[Service]
ExecStart=/usr/bin/python3 /opt/gs-webapp/webapp.py
WorkingDirectory=/opt/gs-webapp
Restart=always
RestartSec=3
User=root

[Install]
WantedBy=multi-user.target
EOF_UNIT
systemctl daemon-reload || fail "daemon-reload မရပါ"
systemctl enable gs-webapp >/dev/null 2>&1 || true
# enable --now does not restart an already-running service — restart explicitly.
systemctl restart gs-webapp || fail "gs-webapp restart မရပါ"

step "Health check: 127.0.0.1:8077"
ok=""
for i in $(seq 1 15); do
  if curl -sf --max-time 3 http://127.0.0.1:8077/api/health >/dev/null 2>&1; then ok=1; break; fi
  sleep 1
done
if [ -z "$ok" ]; then
  journalctl -u gs-webapp -n 20 --no-pager
  fail "gs-webapp health မတက်ပါ"
fi
echo "gs-webapp healthy: $(systemctl is-active gs-webapp)"

step "Caddy: /app/* and /api/* handles on $APP_HOST"
CADDY_BAK="$CADDYFILE.bak.webapp-$(date +%s)"
cp "$CADDYFILE" "$CADDY_BAK" || fail "Caddy backup မရပါ"
echo "Caddy backup: $CADDY_BAK"
python3 - "$CADDYFILE" <<'PYEOF_CADDY'
import re, sys
path = sys.argv[1]
src = open(path).read()
if "127.0.0.1:8077" in src:
    print("caddy: 8077 handles already present - skip")
    sys.exit(10)
lines = src.split("\n")
idx = None
for i, ln in enumerate(lines):
    if re.match(r"^\s*marz\.gloriafreeproton\.io\b", ln):
        idx = i
        break
if idx is None:
    print("caddy: marz.gloriafreeproton.io site block not found", file=sys.stderr)
    sys.exit(2)
j = idx
while "{" not in lines[j]:
    j += 1
    if j >= len(lines):
        print("caddy: site block opening brace not found", file=sys.stderr)
        sys.exit(2)
block = ["\thandle /app/* {", "\t\treverse_proxy 127.0.0.1:8077", "\t}",
         "\thandle /api/* {", "\t\treverse_proxy 127.0.0.1:8077", "\t}"]
lines[j + 1:j + 1] = block
open(path, "w").write("\n".join(lines))
print("caddy: handles inserted as first handles of the site block")
PYEOF_CADDY
rc=$?
if [ $rc -ne 0 ] && [ $rc -ne 10 ]; then
  cp "$CADDY_BAK" "$CADDYFILE"
  fail "Caddy ပြင်တာ မအောင်ပါ - backup ပြန်တင်ပြီး"
fi
if command -v caddy >/dev/null; then
  if ! caddy validate --config "$CADDYFILE" >/dev/null; then
    cp "$CADDY_BAK" "$CADDYFILE"
    fail "caddy validate မအောင်ပါ - backup ပြန်တင်ပြီး"
  fi
  echo "caddy validate OK"
fi
if ! systemctl reload caddy 2>/dev/null; then
  systemctl restart caddy || { cp "$CADDY_BAK" "$CADDYFILE"; fail "caddy reload/restart မရပါ - backup ပြန်တင်ပြီး"; }
fi
echo "caddy reloaded"

step "External verify"
check200() {
  _url=$1; _code=""
  for _i in 1 2 3; do
    _code=$(curl -s -o /dev/null -w "%{http_code}" --max-time 15 "$_url" || echo 000)
    [ "$_code" = "200" ] && return 0
    sleep 2
  done
  echo "verify FAILED: $_url -> HTTP $_code"
  return 1
}
bad=""
check200 "https://$APP_HOST/app/" || bad=1
check200 "https://$APP_HOST/dashboard/" || bad=1
check200 "https://mailapi.busterzone.mobi/health" || bad=1
if [ -n "$bad" ]; then
  cp "$CADDY_BAK" "$CADDYFILE"
  systemctl reload caddy 2>/dev/null || systemctl restart caddy || true
  fail "external verify မအောင်ပါ - Caddy backup ပြန်တင်ပြီး"
fi
echo "external verify OK: /app/ 200, /dashboard/ 200, mailapi /health 200"

step "Bot patch: App button in gs-tgbot"
BOT=/opt/gs-bot/bot.py
if [ -f "$BOT" ]; then
  BOT_BAK="$BOT.bak.webapp-$(date +%s)"
  cp "$BOT" "$BOT_BAK" || fail "bot backup မရပါ"
  echo "bot backup: $BOT_BAK"
  python3 - "$BOT" <<'PYEOF_BOT'
import sys
path = sys.argv[1]
APP_URL = "https://marz.gloriafreeproton.io/app/"
src = open(path).read()
if "web_app" in src and APP_URL in src:
    print("bot: already patched - skip")
    sys.exit(10)
anchor_a = 'MENU = [[{"text": CLAIM_LABEL'
if anchor_a not in src:
    print("bot: MENU anchor not found - abort patch", file=sys.stderr)
    sys.exit(2)
new_first = ('MENU = [[{"text": "\U0001F4F1 App ဖွင့်ရန်", "web_app": {"url": "'
             + APP_URL + '"}}],\n        [{"text": CLAIM_LABEL')
src = src.replace(anchor_a, new_first, 1)
anchor_b = "\n    set_commands()\n"
if anchor_b in src:
    inject = (anchor_b
              + "    try:\n"
              + '        tg_call("setChatMenuButton", {"menu_button": {"type": "web_app", "text": "App",\n'
              + '                "web_app": {"url": "' + APP_URL + '"}}}, timeout=15)\n'
              + "    except Exception as e:\n"
              + '        print("setChatMenuButton web_app failed:", e, file=sys.stderr)\n')
    src = src.replace(anchor_b, inject, 1)
    print("bot: MENU row + menu button patched")
else:
    print("bot: MENU row patched; set_commands() anchor not found - menu button skipped")
open(path, "w").write(src)
PYEOF_BOT
  rc=$?
  if [ $rc -eq 2 ]; then
    echo "bot patch aborted (anchor missing) - bot.py unchanged"
  elif [ $rc -eq 10 ]; then
    echo "bot: already patched - no restart"
  elif [ $rc -ne 0 ]; then
    cp "$BOT_BAK" "$BOT"
    echo "bot patch error - backup restored"
  else
    if ! python3 -m py_compile "$BOT"; then
      cp "$BOT_BAK" "$BOT"
      fail "patched bot.py compile မရပါ - backup ပြန်တင်ပြီး"
    fi
    systemctl restart gs-tgbot || fail "gs-tgbot restart မရပါ"
    sleep 3
    if systemctl is-active --quiet gs-tgbot; then
      echo "gs-tgbot active (patched)"
    else
      cp "$BOT_BAK" "$BOT"
      systemctl restart gs-tgbot || true
      echo "WARNING: patched bot did not stay active - backup restored" >&2
    fi
  fi
else
  echo "WARNING: $BOT not found - bot patch skipped"
fi

step "Summary"
echo "installed files:"
ls -l "$DEST"
echo "gs-webapp service: $(systemctl is-active gs-webapp)"
echo "app URL: $APP_URL"
echo "caddy backup: $CADDY_BAK"
if [ -n "$BOT_BAK" ]; then echo "bot backup: $BOT_BAK"; fi
echo "DONE"
